fn htmlParseHTMLName(mut ctxt: htmlParserCtxtPtr) -> *const xmlChar { unsafe {
    let mut i: c_int = 0;
    let mut loc: [xmlChar; 100] = [0; 100];

    let input = (*ctxt).input;
    let mut cur = (*input).cur;

    let c0 = *cur as c_int;
    if !((c0 >= 0x41 && c0 <= 0x5a)
        || (c0 >= 0x61 && c0 <= 0x7a)
        || c0 == '_' as i32
        || c0 == ':' as i32
        || c0 == '.' as i32)
    {
        return ::core::ptr::null::<xmlChar>();
    }

    while i < HTML_PARSER_BUFFER_SIZE {
        let c = *cur as c_int;
        if !((c >= 0x41 && c <= 0x5a)
            || (c >= 0x61 && c <= 0x7a)
            || (c >= 0x30 && c <= 0x39)
            || c == ':' as i32
            || c == '-' as i32
            || c == '_' as i32
            || c == '.' as i32)
        {
            break;
        }

        loc[i as usize] = if c >= 'A' as i32 && c <= 'Z' as i32 {
            (c + 0x20) as xmlChar
        } else {
            *cur
        };

        i += 1;
        xmlNextChar(ctxt as xmlParserCtxtPtr);
        cur = (*(*ctxt).input).cur;
    }

    let ret = xmlDictLookup((*ctxt).dict, loc.as_mut_ptr(), i);
    if ret.is_null() {
        htmlErrMemory(
            ctxt as xmlParserCtxtPtr,
            ::core::ptr::null::<c_char>(),
        );
    }
    ret
} }

